-- --------------------------------------------------------
-- 7. TABEL: sipd_programs
-- Nomenklatur Program SIPD Kemendagri
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS `sipd_programs` (
  `id` varchar(100) NOT NULL,
  `kode_program` varchar(50) NOT NULL,
  `nama_program` text NOT NULL,
  `bidang_id` varchar(50) DEFAULT NULL,
  `deskripsi` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_prog_kode` (`kode_program`),
  KEY `idx_prog_bidang` (`bidang_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `sipd_programs` (`id`, `kode_program`, `nama_program`, `bidang_id`, `deskripsi`) VALUES
('prog_sekretariat_1_03_01', '1.03.01', 'PROGRAM PENUNJANG URUSAN PEMERINTAHAN DAERAH KABUPATEN/KOTA', 'sekretariat', 'Perencanaan, penganggaran, administrasi keuangan, kepegawaian, pengadaan sarana dan pemeliharaan BMD DINPUTARU'),
('prog_sda_bk_1_03_02', '1.03.02', 'PROGRAM PENGELOLAAN SUMBER DAYA AIR (SDA)', 'sda_bk', 'Pengelolaan sungai, waduk/embung, pintu air, stasiun pompa banjir, dan jaringan irigasi pertanian'),
('prog_cipta_karya_1_03_03', '1.03.03', 'PROGRAM PENGELOLAAN DAN PENGEMBANGAN SISTEM PENYEDIAAN AIR MINUM', 'cipta_karya', 'Pembangunan dan peningkatan SPAM jaringan perpipaan serta sambungan rumah bagi masyarakat'),
('prog_cipta_karya_1_03_05', '1.03.05', 'PROGRAM PENGELOLAAN DAN PENGEMBANGAN SISTEM AIR LIMBAH', 'cipta_karya', 'Pembangunan tangki septik individu/komunal, TPS3R, dan instalasi pengolahan limbah domestik'),
('prog_cipta_karya_1_03_06', '1.03.06', 'PROGRAM PENGELOLAAN DAN PENGEMBANGAN SISTEM DRAINASE', 'cipta_karya', 'Pembangunan, rehabilitasi sistem drainase perkotaan dan saluran pembuang primer/sekunder'),
('prog_cipta_karya_1_03_08', '1.03.08', 'PROGRAM PENATAAN BANGUNAN GEDUNG', 'cipta_karya', 'Pembangunan dan rehabilitasi gedung kantor, fasilitas umum, dan kawasan permukiman'),
('prog_bina_marga_1_03_10', '1.03.10', 'PROGRAM PENYELENGGARAAN JALAN', 'bina_marga', 'Pembangunan, rekonstruksi, pelebaran jalan kabupaten dan pemeliharaan jembatan'),
('prog_sda_bk_1_03_11', '1.03.11', 'PROGRAM PENGEMBANGAN JASA KONSTRUKSI', 'sda_bk', 'Pelatihan tenaga kerja terampil konstruksi, pembinaan kelembagaan dan sertifikasi kompetensi'),
('prog_tata_ruang_1_03_12', '1.03.12', 'PROGRAM PENYELENGGARAAN PENATAAN RUANG', 'tata_ruang', 'Persetujuan substansi RTRW/RDTR, KKPR, sinkronisasi pemanfaatan ruang, dan forum penataan ruang'),
('prog_tata_ruang_2_10_01', '2.10.01', 'PROGRAM REDISTRIBUSI TANAH, DAN GANTI KERUGIAN PROGRAM TANAH KELEBIHAN MAKSIMUM DAN TANAH ABSENTEE', 'tata_ruang', 'Gugus Tugas Reforma Agraria (GTRA) dan redistribusi tanah di Kabupaten Demak'),
('prog_tata_ruang_2_10_02', '2.10.02', 'PROGRAM PENATAGUNAAN TANAH', 'tata_ruang', 'Koordinasi konsolidasi tanah dan penataan penguasaan tanah daerah')
ON DUPLICATE KEY UPDATE `nama_program` = VALUES(`nama_program`), `deskripsi` = VALUES(`deskripsi`);

